import React, { useState, useEffect, useRef } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useDispatch, useSelector } from 'react-redux';
import { AppDispatch, RootState } from '../../store';
import { fetchSession } from '../../store/sessionSlice';
import { sendMessage } from '../../store/messageSlice';
import MessageBubble from './MessageBubble';

const ChatInterface: React.FC = () => {
  const { sessionId } = useParams<{ sessionId: string }>();
  const [message, setMessage] = useState('');
  const [isSending, setIsSending] = useState(false);
  const messageInputRef = useRef<HTMLTextAreaElement>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const dispatch = useDispatch<AppDispatch>();
  const navigate = useNavigate();

  const { currentSession, loading: sessionLoading } = useSelector((state: RootState) => state.sessions);
  const { loading: messageLoading } = useSelector((state: RootState) => state.messages);
  const { user } = useSelector((state: RootState) => state.auth);

  // Scroll to bottom whenever messages change
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [currentSession?.messages]);

  // Fetch session data when component mounts or sessionId changes
  useEffect(() => {
    if (sessionId) {
      dispatch(fetchSession(sessionId));
    }
  }, [dispatch, sessionId]);

  // Handle form submission
  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!message.trim() || isSending || !sessionId || !currentSession || !user) return;

    setIsSending(true);

    try {
      // Get recipient's public key
      // In a real app, this would be more complex with multiple recipients
      const recipientPublicKey = currentSession.participants[0]?.user.publicKey || {};

      await dispatch(sendMessage({
        sessionId,
        content: message,
        recipientPublicKey,
      }));

      // Clear the input field
      setMessage('');

      // Focus on the input field
      messageInputRef.current?.focus();
    } catch (error) {
      console.error('Failed to send message:', error);
    } finally {
      setIsSending(false);
    }
  };

  // Handle textarea input change
  const handleChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    setMessage(e.target.value);
  };

  // Handle textarea keydown (for Shift+Enter and Enter submission)
  const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSubmit(e);
    }
  };

  // Render loading state
  if (sessionLoading) {
    return (
      <div className="flex items-center justify-center h-screen">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-teal-500 mx-auto"></div>
          <p className="mt-4 text-gray-600">Loading conversation...</p>
        </div>
      </div>
    );
  }

  // Render 404 if session not found
  if (!sessionLoading && !currentSession) {
    return (
      <div className="flex flex-col items-center justify-center h-screen">
        <h2 className="text-2xl font-bold text-gray-800 mb-4">Session Not Found</h2>
        <p className="text-gray-600 mb-8">The session you're looking for doesn't exist or you don't have access to it.</p>
        <button
          onClick={() => navigate('/sessions')}
          className="px-4 py-2 bg-teal-500 text-white rounded-md hover:bg-teal-600"
        >
          Back to Sessions
        </button>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-[calc(100vh-5rem)] max-w-4xl mx-auto bg-white rounded-lg shadow-md overflow-hidden">
      {/* Chat Header */}
      <div className="bg-gradient-to-r from-teal-500 to-blue-500 text-white p-4 shadow">
        <div className="flex items-center justify-between">
          <div>
            <h2 className="text-xl font-semibold">
              {currentSession?.type === 'individual'
                ? 'Individual Session with Coco'
                : `Session with ${currentSession?.participants
                    .filter(p => p.user.id !== user?.id)
                    .map(p => p.user.pseudonym)
                    .join(', ')}`}
            </h2>
            <p className="text-sm text-white/80">
              Started on {new Date(currentSession?.createdAt || '').toLocaleDateString()}
            </p>
          </div>

          <div className="flex space-x-2">
            {currentSession?.endedAt ? (
              <span className="px-3 py-1 bg-gray-200 text-gray-800 rounded-full text-sm">
                Ended
              </span>
            ) : (
              <button
                onClick={() => navigate('/sessions')}
                className="px-3 py-1 bg-white/20 text-white rounded-md hover:bg-white/30"
              >
                Back
              </button>
            )}
          </div>
        </div>
      </div>

      {/* Messages Container */}
      <div className="flex-1 overflow-y-auto p-4 bg-gray-50">
        <div className="space-y-4">
          {currentSession?.messages && currentSession.messages.length > 0 ? (
            currentSession.messages.map((msg) => (
              <MessageBubble
                key={msg.id}
                message={msg}
                isUser={msg.senderId === user?.id && !msg.isAi}
              />
            ))
          ) : (
            <div className="text-center py-8">
              <p className="text-gray-500">
                This is the beginning of your conversation. Say hello to Coco!
              </p>
            </div>
          )}
          <div ref={messagesEndRef} />
        </div>
      </div>

      {/* Message Input */}
      {!currentSession?.endedAt ? (
        <form onSubmit={handleSubmit} className="border-t border-gray-200 p-4 bg-white">
          <div className="flex items-end space-x-2">
            <div className="flex-1">
              <textarea
                ref={messageInputRef}
                value={message}
                onChange={handleChange}
                onKeyDown={handleKeyDown}
                placeholder="Type your message..."
                className="w-full p-2 border border-gray-300 rounded-md focus:ring-2 focus:ring-teal-500 focus:border-transparent resize-none"
                rows={3}
                disabled={messageLoading || isSending}
              />
              <p className="text-xs text-gray-500 mt-1">
                Press Enter to send, Shift+Enter for new line
              </p>
            </div>

            <button
              type="submit"
              disabled={!message.trim() || messageLoading || isSending}
              className={`px-4 py-2 rounded-md ${
                !message.trim() || messageLoading || isSending
                  ? 'bg-gray-300 text-gray-500 cursor-not-allowed'
                  : 'bg-teal-500 text-white hover:bg-teal-600'
              }`}
            >
              {messageLoading || isSending ? (
                <span className="flex items-center">
                  <svg className="animate-spin -ml-1 mr-2 h-4 w-4 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                    <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                    <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                  </svg>
                  Sending
                </span>
              ) : (
                'Send'
              )}
            </button>
          </div>

          <div className="mt-2 text-xs text-gray-500 text-center">
            Remember: Coco is a supportive AI counselor, not a replacement for professional therapy.
          </div>
        </form>
      ) : (
        <div className="border-t border-gray-200 p-4 bg-gray-100 text-center">
          <p className="text-gray-600">This session has ended.</p>
          <button
            onClick={() => navigate('/sessions/new')}
            className="mt-2 px-4 py-2 bg-teal-500 text-white rounded-md hover:bg-teal-600"
          >
            Start New Session
          </button>
        </div>
      )}
    </div>
  );
};

export default ChatInterface;
